#include "mock_dsp_dependencies.h"

#include <stdint.h>
#include <string.h>

#include "pitch_detector.h"
#include "pitch_shifter.h"

static MockDspInteractions g_interactions;
static bool g_detector_valid;
static float g_detector_pitch_hz;
static float g_detector_confidence;
static bool g_shifter_ratio_success;
static bool g_shifter_process_success;

/** Reset mock configuration and all recorded interactions. */
void MockDsp_Reset(void)
{
    memset(&g_interactions, 0, sizeof(g_interactions));
    g_detector_valid = false;
    g_detector_pitch_hz = 0.0f;
    g_detector_confidence = 0.0f;
    g_shifter_ratio_success = true;
    g_shifter_process_success = true;
}

/** Configure the detector test double's current result. */
void MockDsp_SetDetectorResult(bool valid, float pitch_hz, float confidence)
{
    g_detector_valid = valid;
    g_detector_pitch_hz = pitch_hz;
    g_detector_confidence = confidence;
}

/** Configure success/failure of ratio-setting calls. */
void MockDsp_SetShifterRatioResult(bool success)
{
    g_shifter_ratio_success = success;
}

/** Configure success/failure of pitch-shifter processing calls. */
void MockDsp_SetShifterProcessResult(bool success)
{
    g_shifter_process_success = success;
}

/** Return a copy of the recorded dependency interactions. */
MockDspInteractions MockDsp_GetInteractions(void)
{
    return g_interactions;
}

/** Mock detector initialisation delegates to the mock reset implementation. */
void PitchDetector_Init(PitchDetector *detector)
{
    PitchDetector_Reset(detector);
}

/** Mock detector reset clears caller-owned state when supplied. */
void PitchDetector_Reset(PitchDetector *detector)
{
    if (detector != NULL)
    {
        memset(detector, 0, sizeof(*detector));
    }
}

/** Record a detector call and return the configured pitch/confidence result. */
bool PitchDetector_ProcessBlock(PitchDetector *detector,
                                const int16_t *input,
                                size_t sample_count,
                                float *pitch_hz,
                                float *confidence)
{
    (void)detector;
    (void)input;
    g_interactions.detector_process_calls++;
    g_interactions.detector_last_sample_count = sample_count;

    if (pitch_hz != NULL) *pitch_hz = g_detector_valid ? g_detector_pitch_hz : 0.0f;
    if (confidence != NULL) *confidence = g_detector_confidence;
    return g_detector_valid;
}

/** Mock shifter initialisation delegates to the mock reset implementation. */
void PitchShifter_Init(PitchShifter *shifter)
{
    PitchShifter_Reset(shifter);
}

/** Mock shifter reset clears state and restores unity ratios. */
void PitchShifter_Reset(PitchShifter *shifter)
{
    if (shifter != NULL)
    {
        memset(shifter, 0, sizeof(*shifter));
        shifter->current_ratio = 1.0f;
        shifter->target_ratio = 1.0f;
    }
}

/** Record the requested ratio and return the configured success result. */
bool PitchShifter_SetRatio(PitchShifter *shifter, float ratio)
{
    (void)shifter;
    g_interactions.shifter_set_ratio_calls++;
    g_interactions.shifter_last_ratio = ratio;
    return g_shifter_ratio_success;
}

/** Record processing and copy input to output when configured to succeed. */
bool PitchShifter_ProcessBlock(PitchShifter *shifter,
                               const int16_t *input,
                               int16_t *output,
                               size_t sample_count)
{
    (void)shifter;
    g_interactions.shifter_process_calls++;
    g_interactions.shifter_last_sample_count = sample_count;

    if (!g_shifter_process_success)
    {
        return false;
    }

    if ((input == NULL) || (output == NULL))
    {
        return false;
    }

    for (size_t i = 0U; i < sample_count; ++i)
    {
        output[i] = input[i];
    }
    return true;
}

/** Mock: every call reports a brand-new estimate (0 samples ago), so the
 *  Autotune takes the configured detector result at once. */
int32_t PitchDetector_SamplesSinceEstimate(const PitchDetector *detector)
{
    (void)detector;
    return 0;
}

/** Mock: store the hard-tune switch like the real shifter. */
void PitchShifter_SetHardTune(PitchShifter *shifter, bool hard_tune)
{
    if (shifter != NULL)
    {
        shifter->hard_tune = hard_tune;
    }
}
